<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { fetchTeachingScopes,type TeachingScope } from '../../api/teacher';import { createPaper,createRulePaper,fetchPaperQuality,fetchPaperQuestions,fetchPapers,publishPaper,type PaperQualityAssessment,type PaperQuestionOption } from '../../api/teacher/papers';import ScientificText from '../../components/question/ScientificText.vue'
const router=useRouter();const scopes=ref<TeachingScope[]>([]);const papers=ref<any[]>([]);const questions=ref<PaperQuestionOption[]>([]);const mode=ref<'MANUAL'|'RULE'>('MANUAL');const selected=ref<(PaperQuestionOption&{score:number})[]>([]);const publishVisible=ref(false),publishPaperId=ref(0),quality=ref<PaperQualityAssessment>();const publishForm=reactive({teachingScopeId:undefined as number|undefined,deadline:''});const form=reactive({subjectId:undefined as number|undefined,name:'',knowledgePointId:undefined as number|undefined,questionType:'',difficulty:undefined as number|undefined,keyword:'',knowledgePointIds:'',questionTypes:['SINGLE_CHOICE'],difficulties:[1,2,3],count:10,totalScore:100});const total=computed(()=>selected.value.reduce((sum,item)=>sum+Number(item.score||0),0));
async function load(){scopes.value=(await fetchTeachingScopes()).filter(item=>item.teachingStatus==='ACTIVE');papers.value=await fetchPapers()}
async function search(){if(!form.subjectId)return;questions.value=await fetchPaperQuestions({subjectId:form.subjectId,knowledgePointId:form.knowledgePointId,questionType:form.questionType||undefined,difficulty:form.difficulty,keyword:form.keyword||undefined})}
function add(question:PaperQuestionOption){if(!selected.value.some(item=>item.id===question.id))selected.value.push({...question,score:5})}function remove(index:number){selected.value.splice(index,1)}function move(index:number,delta:number){const target=index+delta;if(target<0||target>=selected.value.length)return;const [item]=selected.value.splice(index,1);selected.value.splice(target,0,item)}
async function save(){try{if(mode.value==='MANUAL')await createPaper({subjectId:form.subjectId,name:form.name,mode:'MANUAL',items:selected.value.map(item=>({questionId:item.id,score:item.score}))});else await createRulePaper({subjectId:form.subjectId,name:form.name,knowledgePointIds:form.knowledgePointIds.split(/[,，\s]+/).filter(Boolean).map(Number),questionTypes:form.questionTypes,difficulties:form.difficulties,count:form.count,totalScore:form.totalScore});ElMessage.success('试卷已冻结保存');selected.value=[];await load()}catch(error:any){ElMessage.warning(error.message||'组卷失败') }}
async function openPublish(row:any){publishPaperId.value=row.id;publishForm.teachingScopeId=scopes.value.find(scope=>scope.subjectId===row.subjectId)?.teachingAssignmentId;publishForm.deadline='';quality.value=await fetchPaperQuality(row.id);publishVisible.value=true}
async function publish(){if(!publishForm.teachingScopeId||!publishForm.deadline)return;await publishPaper(publishPaperId.value,{teachingScopeId:publishForm.teachingScopeId,deadline:new Date(publishForm.deadline).toISOString().slice(0,19)});ElMessage.success('试卷已发布，题目与 STANDARD 已冻结');publishVisible.value=false}
watch(()=>form.subjectId,()=>{questions.value=[];selected.value=[]});onMounted(load)
</script>
<template><main class="paper-builder"><div class="heading"><div><p>TEACHER PAPER STUDIO</p><h1>组卷与打印</h1><span>从本人任教学科的已发布题目中手动选题，或按规则生成冻结试卷。</span></div><el-segmented v-model="mode" :options="[{label:'手动组卷',value:'MANUAL'},{label:'规则组卷',value:'RULE'}]"/></div><el-form label-position="top"><div class="base-fields"><el-form-item label="任教学科"><el-select v-model="form.subjectId"><el-option v-for="scope in scopes" :key="scope.subjectId" :label="scope.subjectName" :value="scope.subjectId"/></el-select></el-form-item><el-form-item label="试卷名称"><el-input v-model="form.name" maxlength="120"/></el-form-item></div><template v-if="mode==='MANUAL'"><section class="filters"><el-input v-model="form.keyword" placeholder="题干关键词"/><el-select v-model="form.questionType" clearable placeholder="题型"><el-option label="单选" value="SINGLE_CHOICE"/><el-option label="多选" value="MULTIPLE_CHOICE"/><el-option label="填空" value="FILL_BLANK"/></el-select><el-input-number v-model="form.difficulty" :min="1" :max="5" placeholder="难度"/><el-button :disabled="!form.subjectId" @click="search">检索已发布题目</el-button></section><div class="manual-grid"><section><h2>题库结果</h2><article v-for="question in questions" :key="question.id" class="question-card"><div><el-tag>{{question.type}}</el-tag><span>难度 {{question.difficulty}}</span></div><ScientificText :content="question.stem"/><small>{{question.knowledgePoints.join(' · ')}}</small><el-button @click="add(question)">加入试卷</el-button></article><el-empty v-if="!questions.length" description="请选择学科并检索题目"/></section><section class="basket"><h2>题篮 · {{selected.length}} 题 · {{total}} 分</h2><article v-for="(question,index) in selected" :key="question.id"><strong>{{index+1}}.</strong><ScientificText :content="question.stem"/><el-input-number v-model="question.score" :min="0.5" :step="0.5"/><div><el-button :disabled="index===0" @click="move(index,-1)">上移</el-button><el-button :disabled="index===selected.length-1" @click="move(index,1)">下移</el-button><el-button type="danger" plain @click="remove(index)">移除</el-button></div></article><el-empty v-if="!selected.length" description="从左侧加入题目"/></section></div></template><template v-else><div class="rule-fields"><el-form-item label="知识点 ID（可选）"><el-input v-model="form.knowledgePointIds"/></el-form-item><el-form-item label="题型"><el-checkbox-group v-model="form.questionTypes"><el-checkbox value="SINGLE_CHOICE">单选</el-checkbox><el-checkbox value="MULTIPLE_CHOICE">多选</el-checkbox><el-checkbox value="FILL_BLANK">填空</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="数量"><el-input-number v-model="form.count" :min="1" :max="100"/></el-form-item><el-form-item label="目标总分"><el-input-number v-model="form.totalScore" :min="1"/></el-form-item></div></template><el-button type="primary" :disabled="!form.subjectId||!form.name.trim()||(mode==='MANUAL'&&!selected.length)" @click="save">保存冻结试卷</el-button></el-form><h2>已保存试卷</h2><el-table :data="papers"><el-table-column prop="name" label="试卷"/><el-table-column prop="questionCount" label="题数"/><el-table-column prop="totalScore" label="总分"/><el-table-column label="操作" min-width="300"><template #default="{row}"><el-button @click="router.push(`/teacher/papers/${row.id}/student`)">学生版</el-button><el-button @click="router.push(`/teacher/papers/${row.id}/answer`)">答案解析版</el-button><el-button type="primary" plain @click="openPublish(row)">发布到班级</el-button></template></el-table-column></el-table><el-dialog v-model="publishVisible" title="发布冻结试卷" width="min(560px,calc(100vw - 24px))"><el-alert title="发布后题干、选项、分值、STANDARD 全部冻结" type="info" :closable="false"/><el-form label-position="top"><el-form-item label="本人 ACTIVE 任课班级"><el-select v-model="publishForm.teachingScopeId"><el-option v-for="scope in scopes" :key="scope.teachingAssignmentId" :label="`${scope.className} · ${scope.subjectName}`" :value="scope.teachingAssignmentId"/></el-select></el-form-item><el-form-item label="截止时间"><el-date-picker v-model="publishForm.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></el-form><section v-if="quality" class="quality"><strong>{{quality.notice}}</strong><p v-for="item in quality.coverage" :key="item">{{item}}</p><el-alert v-for="risk in quality.risks" :key="risk" :title="risk" type="warning" :closable="false"/></section><template #footer><el-button @click="publishVisible=false">取消</el-button><el-button type="primary" :disabled="!publishForm.teachingScopeId||!publishForm.deadline" @click="publish">确认发布</el-button></template></el-dialog></main></template>
<style scoped>.paper-builder{max-width:1200px;margin:0 auto;padding:28px}.heading{display:flex;justify-content:space-between;gap:24px;align-items:end}.heading p{letter-spacing:.12em;color:#547a87}.heading h1{margin:4px 0}.paper-builder>.el-form{margin:24px 0;padding:22px;border:1px solid var(--el-border-color);border-radius:18px}.base-fields,.rule-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px;margin:10px 0 18px}.manual-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.manual-grid>section{min-width:0;padding:16px;border:1px solid var(--el-border-color-light);border-radius:14px}.question-card,.basket article{display:grid;gap:8px;padding:14px 0;border-bottom:1px solid var(--el-border-color-lighter)}.question-card>div{display:flex;gap:10px;align-items:center}.question-card small{color:var(--el-text-color-secondary)}.basket article{grid-template-columns:auto 1fr auto}.basket article>div{grid-column:2/4}@media(max-width:800px){.heading{align-items:stretch;flex-direction:column}.base-fields,.rule-fields,.filters,.manual-grid{grid-template-columns:1fr}.basket article{grid-template-columns:auto 1fr}.basket article>div{grid-column:1/3}}</style>
